arguments.new_str:
var builder = WebApplication.CreateBuilder(args);

// Fix 5: Scoped IUserService cannot be consumed by a singleton — promote to Scoped
//         (ValidateOnBuild/ValidateScopes now enabled by default in Development)
builder.Services.AddScoped<IUserService, UserService>();
builder.Services.AddScoped<ICacheService>(sp =>
    new CacheService(sp.GetRequiredService<IUserService>()));

// Fix 1: HttpClientFactory now uses SocketsHttpHandler by default — cast would throw
builder.Services.AddHttpClient("api")
    .ConfigurePrimaryHttpMessageHandler(() => new SocketsHttpHandler { UseCookies = false });

// Fix 2: Forwarded Headers middleware now ignores headers from unknown proxies —
//         add trusted proxy addresses (adjust to your environment)
builder.Services.Configure<ForwardedHeadersOptions>(options =>
{
    options.ForwardedHeaders = ForwardedHeaders.XForwardedFor;
    options.KnownProxies.Add(System.Net.IPAddress.Parse("127.0.0.1"));
});

// Fix 3: HttpClientFactory Trace-level logs now redact all header values by default —
//         allowlist non-sensitive headers you need for debugging
builder.Services.ConfigureHttpClientDefaults(b =>
    b.RedactLoggedHeaders(h =>
        h != "X-Request-Id" && h != "X-Correlation-Id" && h != "Accept"));

var app = builder.Build();
app.UseForwardedHeaders();
app.Run();

